WITH with_gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_burst FROM transactions), sessions_transactions AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, SUM(is_new_burst) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT s.id, s.account_id, s.txn_type, s.amount, s.txn_time, s.merchant, s.is_flagged, (SELECT SUM(x.amount) FROM transactions x WHERE x.account_id = s.account_id) AS sum_transaction_amount FROM sessions_transactions s;
